# Rebuild Mogra research CSVs with correct CSV quoting.
# Reconstructs the malformed handwritten CSVs into structurally valid ones and
# applies the owner-requested corrections (supplier/resource split, Especias Moy
# reclassification, Pearl product-form granularity, count denominators).
import csv, os

D = os.path.join("docs", "mogra-organics-research-2026-10-02")
os.makedirs(D, exist_ok=True)

def w(name, header, rows):
    p = os.path.join(D, name)
    n = len(header)
    bad = 0
    fixed = []
    for i, r in enumerate(rows, 1):
        if len(r) != n:
            bad += 1
            print(f"  !! {name} row {i}: {len(r)} cols, expected {n} -> padding/truncating")
            r = (list(r) + [""] * n)[:n]
        fixed.append(r)
    with open(p, "w", newline="", encoding="utf-8") as f:
        cw = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
        cw.writerow(header)
        for r in fixed:
            cw.writerow(r)
    print(f"{name}: {len(fixed)} data rows, {bad} column mismatches")

